def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    def f(n: int) -> int:
        if n < 0:
            return 0
        s_int = int(s)
        l = len(s)
        if n < s_int:
            return 0

        s_digits = [int(c) for c in s]
        if any(d > limit for d in s_digits):
            return 0

        L_n = len(str(n))

        def count_valid_upto(K: int) -> int:
            if K < 0:
                return 0
            digits = [int(c) for c in str(K)]
            n_d = len(digits)
            total = 0

            # Precompute (limit + 1)^i for i in 0..n_d
            pow_table = [(limit + 1) ** i for i in range(n_d + 1)]

            for i in range(n_d):
                d = digits[i]
                # Choices for current digit: 0 to min(d-1, limit)
                upper = min(d - 1, limit)
                if upper >= 0:
                    count_choices = upper + 1
                    rem_len = n_d - i - 1
                    total += count_choices * pow_table[rem_len]

                # Check if we can continue with d
                if d > limit:
                    return total

            total += 1
            return total

        ans = 0

        # Case 1: x < 10^(L_n - 1) (length < L_n)
        if L_n > l:
            max_val_short = 10 ** (L_n - 1) - 1
            if max_val_short >= s_int:
                max_p_short = (max_val_short - s_int) // (10 ** l)
                if max_p_short >= 0:
                    ans += count_valid_upto(max_p_short)

        # Case 2: 10^(L_n - 1) <= x <= n (length == L_n)
        min_val_long = 10 ** (L_n - 1)
        max_val_long = n

        if max_val_long >= min_val_long:
            p_min = (min_val_long - s_int + 10 ** l - 1) // (10 ** l)
            if p_min < 0:
                p_min = 0

            p_max = (max_val_long - s_int) // (10 ** l)
            if p_max < 0:
                p_max = -1

            if p_min <= p_max:
                ans += count_valid_upto(p_max) - count_valid_upto(p_min - 1)

        return ans

    return f(finish) - f(start - 1)

from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    if h <= 0 or w <= 0:
        return False

    # Early area check: if the total area of all available tiles is less than the grid area, it's impossible.
    if sum(a * b for a, b in tiles) < h * w:
        return False

    def solve(grid: List[List[int]], used: List[bool]) -> bool:
        # Find the first empty cell (row-major order). If none, all covered.
        r0 = -1
        c0 = -1
        for i in range(h):
            for j in range(w):
                if grid[i][j] == -1:
                    r0 = i
                    c0 = j
                    break
            if r0 != -1:
                break

        if r0 == -1:
            return True

        # Iterate through tiles to place in the first empty cell.
        for i in range(n):
            if used[i]:
                continue

            a, b = tiles[i]
            orientations = [(a, b)]
            if a != b:
                orientations.append((b, a))

            for ra, ca in orientations:
                # Check bounds
                if r0 + ra <= h and c0 + ca <= w:
                    # Check if all cells in the rectangle are empty
                    can_place = True
                    for dr in range(ra):
                        for dc in range(ca):
                            if grid[r0 + dr][c0 + dc] != -1:
                                can_place = False
                                break
                        if not can_place:
                            break

                    if can_place:
                        # Place the tile
                        for dr in range(ra):
                            for dc in range(ca):
                                grid[r0 + dr][c0 + dc] = i
                        used[i] = True

                        if solve(grid, used):
                            return True

                        # Unplace the tile (backtrack)
                        for dr in range(ra):
                            for dc in range(ca):
                                grid[r0 + dr][c0 + dc] = -1
                        used[i] = False

        return False

    grid = [[-1 for _ in range(w)] for _ in range(h)]
    used = [False] * n
    return solve(grid, used)

def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    # Check if suffix itself violates the digit limit constraint
    for ch in s:
        if int(ch) > limit:
            return 0

    n = len(s)
    base = 10 ** n
    val_s = int(s)

    # If the suffix is too long such that even the smallest powerful integer (just s) is > finish
    if val_s > finish:
        return 0

    # Smallest y such that y * base + val_s >= start
    if start <= val_s:
        y_min = 0
    else:
        y_min = (start - val_s + base - 1) // base

    # Largest y such that y * base + val_s <= finish
    if finish >= val_s:
        y_max = (finish - val_s) // base
    else:
        y_max = -1

    if y_min > y_max:
        return 0

    def _count_up_to(n_val: int) -> int:
        if n_val < 0:
            return 0
        s_n = str(n_val)
        L = len(s_n)
        res = 1  # for 0

        # Count numbers with exactly k digits, for k from 1 to L-1
        for k in range(1, L):
            res += limit * (limit + 1) ** (k - 1)

        # Count numbers with exactly L digits that are <= n_val
        for i in range(L):
            di = int(s_n[i])
            if i == 0:
                start_d = 1
            else:
                start_d = 0

            if di > limit:
                if di > start_d:
                    res += (limit - start_d + 1) * ((limit + 1) ** (L - i - 1))
                break
            else:
                if di > start_d:
                    res += (di - start_d) * ((limit + 1) ** (L - i - 1))

                if i == L - 1:
                    res += 1

        return res

    return _count_up_to(y_max) - _count_up_to(y_min - 1)

