def count_ways_to_stair(k: int) -> int:
    if k == 0:
        return 2
    if k == 1:
        return 4
    if k % 2 == 0:
        return 0
    x = k - 1
    bits = x.bit_length()
    res = 0
    for i in range(bits):
        if x & (1 << i):
            if i == 0:
                res += 4
            else:
                res += i - 1
    return res

def count_valid_colorings(n: int, m: int) -> int:
    MOD = 998244353
    # Number of valid colorings of a cycle C_n with m colors is
    # (m-1)^n + (-1)^n * (m-1).
    a = (m - 1) % MOD
    if n % 2 == 1:
        result = (pow(a, n, MOD) - a) % MOD
    else:
        result = (pow(a, n, MOD) + a) % MOD
    return result

