def count_square_permutations(n: int, s: str) -> int:
    target = Counter(s)
    result = set()
    limit = isqrt(10 ** n)  # floor sqrt of 10^n
    for x in range(0, limit + 1):
        sq = x * x
        sd = str(sq)
        if len(sd) > n:
            continue
        padded = sd.rjust(n, '0')
        if Counter(padded) == target:
            result.add(sq)
    return len(result)

