def find_cube_placement(V1: int, V2: int, V3: int) -> Optional[Tuple[int, int, int, int, int, int, int, int, int]]:
    # Necessary condition: V1 + 2*V2 + 3*V3 == 3*7^3 = 1029
    if V1 < 0 or V2 < 0 or V3 < 0:
        return None
    if V3 > 343 or V2 > 343 or V1 > 1029:
        return None
    if V1 + 2 * V2 + 3 * V3 != 1029:
        return None

    # Special easy cases
    if V3 == 343 and V2 == 0 and V1 == 0:
        return (0, 0, 0, 0, 0, 0, 0, 0, 0)

    # No overlap: V1=343*3=1029, V2=0, V3=0
    if V1 == 1029 and V2 == 0 and V3 == 0:
        return (0, 0, 0, 10, 0, 0, 0, 10, 0)

    def overlap_1d(d: int) -> int:
        if d <= -7 or d >= 7:
            return 0
        return 7 - abs(d)

    def triple_1d(d1: int, d2: int) -> int:
        lo = max(0, d1, d2)
        hi = min(7, d1 + 7, d2 + 7)
        return max(0, hi - lo)

    # Pre-compute overlap lengths for all possible offsets in [-7, 7]
    overlap_cache = {}
    for d in range(-7, 8):
        overlap_cache[d] = overlap_1d(d)

    # Search over relative positions
    # Fix cube1 at (0,0,0)
    # Cube2 at (dx1, dy1, dz1), cube3 at (dx2, dy2, dz2)
    for dx1 in range(-7, 8):
        o12x = overlap_cache[dx1]
        for dy1 in range(-7, 8):
            o12y = overlap_cache[dy1]
            o12xy = o12x * o12y
            for dz1 in range(-7, 8):
                o12z = overlap_cache[dz1]
                o12 = o12xy * o12z
                for dx2 in range(-7, 8):
                    o13x = overlap_cache[dx2]
                    o23x = overlap_cache[dx2 - dx1]
                    tx = triple_1d(dx1, dx2)
                    for dy2 in range(-7, 8):
                        o13y = overlap_cache[dy2]
                        o23y = overlap_cache[dy2 - dy1]
                        ty = triple_1d(dy1, dy2)
                        txy = tx * ty
                        for dz2 in range(-7, 8):
                            o13z = overlap_cache[dz2]
                            o23z = overlap_cache[dz2 - dz1]
                            tz = triple_1d(dz1, dz2)

                            o13 = (o13x * o13y) * o13z
                            o23 = (o23x * o23y) * o23z
                            o123 = txy * tz

                            S1 = o12 + o13 + o23
                            V2_calc = 2 * S1 - 3 * o123

                            if V2_calc == V2 and o123 == V3:
                                # V1 is determined by V2 and V3 via the conservation equation
                                # V1 = 1029 - 2*V2 - 3*V3
                                return (0, 0, 0, dx1, dy1, dz1, dx2, dy2, dz2)

    return None

