def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    grid_area = h * w

    # Normalize tiles to unique orientations for placement checks, 
    # but keep original indices for selection (since tiles are distinct items)
    # We need to find a subset of tiles such that their total area is grid_area.

    # Early exit: if no subset sums to grid_area, return False
    # n <= 7, so 2^7 = 128 subsets max. Very fast.

    # Generate all possible subsets of indices
    # For each subset, check if sum of areas == grid_area
    # If yes, try to tile the grid with these specific tiles (each used exactly once)

    # Optimization: If a tile dimension is > h and > w (even rotated), it cannot be used.
    # But rotation handles that. If min(a,b) > max(h,w) or max(a,b) > max(h,w) and it doesn't fit in any orientation, skip.

    # Actually, simplest is just to iterate subsets and run the tiling solver if area matches.

    def can_tile_with_subset(indices: Tuple[int, ...]) -> bool:
        # Filter out tiles that cannot possibly fit in the grid (dimensions too large)
        # If a tile is a x b, it must fit as (a, b) or (b, a) in (h, w)
        valid_tiles = []
        for idx in indices:
            a, b = tiles[idx]
            if (a <= h and b <= w) or (b <= h and a <= w):
                valid_tiles.append((a, b))
            else:
                return False # If a tile in the subset can't fit, this subset is invalid

        # Now try to place all tiles in valid_tiles onto the grid
        # Using backtracking on the first empty cell

        used = [False] * len(valid_tiles)
        grid = [[0] * w for _ in range(h)]

        def place(r, c, th, tw):
            for i in range(th):
                for j in range(tw):
                    grid[r+i][c+j] = 1

        def unplace(r, c, th, tw):
            for i in range(th):
                for j in range(tw):
                    grid[r+i][c+j] = 0

        def can_place(r, c, th, tw):
            if r + th > h or c + tw > w:
                return False
            for i in range(th):
                for j in range(tw):
                    if grid[r+i][c+j] != 0:
                        return False
            return True

        def dfs():
            # Find the first empty cell (row-major order)
            target_r, target_c = -1, -1
            for i in range(h):
                for j in range(w):
                    if grid[i][j] == 0:
                        target_r, target_c = i, j
                        break
                if target_r != -1:
                    break

            if target_r == -1:
                return True # All cells covered

            # Try every unused tile
            for k in range(len(valid_tiles)):
                if used[k]:
                    continue

                a, b = valid_tiles[k]
                # Try orientation (a, b)
                if can_place(target_r, target_c, a, b):
                    place(target_r, target_c, a, b)
                    used[k] = True
                    if dfs():
                        return True
                    used[k] = False
                    unplace(target_r, target_c, a, b)

                # Try orientation (b, a) if different
                if a != b:
                    if can_place(target_r, target_c, b, a):
                        place(target_r, target_c, b, a)
                        used[k] = True
                        if dfs():
                            return True
                        used[k] = False
                        unplace(target_r, target_c, b, a)

            return False

        return dfs()

    # Iterate through all non-empty subsets of tile indices
    # Note: It is possible that an empty set works if h*w == 0, but h,w >= 1 so grid_area >= 1.
    # So we only consider non-empty subsets.

    # To be efficient, we can sort tiles by area descending or something, but n is small.
    # We can also prune subsets whose area > grid_area.

    indices = list(range(n))
    for k in range(1, n + 1):
        for subset in combinations(indices, k):
            # Calculate total area
            area_sum = 0
            valid = True
            for idx in subset:
                a, b = tiles[idx]
                # Check if tile can fit in grid at all
                if not ((a <= h and b <= w) or (b <= h and a <= w)):
                    valid = False
                    break
                area_sum += a * b
                if area_sum > grid_area:
                    valid = False
                    break

            if not valid or area_sum != grid_area:
                continue

            if can_tile_with_subset(subset):
                return True

    return False

def count_ways_to_stair(k: int) -> int:
    if k > (1 << 31) - 1:
        return 0

    def comb(n, r):
        if r < 0 or r > n:
            return 0
        if r == 0 or r == n:
            return 1
        r = min(r, n - r)
        res = 1
        for i in range(r):
            res = res * (n - i) // (i + 1)
        return res

    ans = 0
    for m in range(32):
        d = (1 << m) - k
        if d < 0:
            continue
        if d > m + 1:
            continue
        ans += comb(m + 1, d)
    return ans

