                    ans += 1 if i == 0 else (limit + 1) ** (len(ds) - i - 1)
        return ans + 1

    return count_up_to(p_max) - count_up_to(p_min - 1)

def count_valid_colorings(n: int, m: int) -> int:
    MOD = 998244353
    base = (m - 1) % MOD
    power = pow(base, n, MOD)
    if n % 2 == 0:
        return (power + base) % MOD
    else:
        return (power - base) % MOD

from typing import Optional, List
import itertools

def solve_grid(n: int, r: str, c: str) -> Optional[List[str]]:
    def is_valid(grid):
        for i in range(n):
            letters = [ch for ch in grid[i] if ch != '.']
            if len(letters) != 3:
                return False
            if len(set(letters)) != 3:
                return False
            if grid[i][0] != '.':
                if grid[i][0] != r[i]:
                    return False
            else:
                # leftmost char should be the first non-dot
                for ch in grid[i]:
                    if ch != '.':
                        if ch != r[i]:
                            return False
                        break
        for j in range(n):
            col = [grid[i][j] for i in range(n)]
            letters = [ch for ch in col if ch != '.']
            if len(letters) != 3:
                return False
            if len(set(letters)) != 3:
                return False
            if col[0] != '.':
                if col[0] != c[j]:
                    return False
            else:
                for ch in col:
                    if ch != '.':
                        if ch != c[j]:
                            return False
                        break
        return True

    if n == 3:
        chars = 'ABC'
        for perm in itertools.permutations(chars):
            grid = list(perm)
            if is_valid(grid):
                return grid
        return None

    grid = [['.'] * n for _ in range(n)]

    def backtrack(row):
        if row == n:
            return is_valid(grid)
        # We need to place 3 non-dot chars in this row, and 3 non-dot chars in each col overall.
        # Since n is small, we can just try to fill row by row.
        # However, the constraints on columns make simple row-by-row backtracking tricky if we don't track col counts.
        # Let's track col_counts: dict col -> {letter: count}
        # And for each col, we need exactly 3 total non-dots.
        # The 'topmost' constraint is specific: the first non-dot in the column must be c[j].

        # To keep it simple and correct for n<=5, let's just generate all possible row configurations that match r[row]
        # and have exactly one A, one B, one C, then check global constraints at the end? 
        # No, we should prune early.

        # Let's implement a full backtracking on cells.
        # Actually, given n<=5, we can iterate over combinations of positions for the 3 letters in each row.
        pass

    # The logic above is incomplete. Let's try a different approach: generate all valid rows for each row i
    # that satisfy the row constraint (one A, one B, one C, leftmost matches r[i]) and then combine them to satisfy column constraints.

    def get_possible_rows(i):
        row_chars = 'ABC'
        possibilities = []
        for perm in itertools.permutations(row_chars):
            row = ['.'] * n
            # The leftmost non-dot must be r[i].
            # This means for all j < pos, row[j] == '.', and row[pos] == r[i] where pos is the first non-dot.
            # Since we are placing 3 letters, the first non-dot can be at index 0, 1, or 2 (max 2 because we need 3 letters and n>=3).
            # Wait, if n=3, first non-dot must be 0. If n=4, 0 or 1. If n=5, 0, 1, or 2.

            # A simpler way: iterate over all subsets of 3 positions and all permutations of ABC on those positions.
            for pos_indices in itertools.combinations(range(n), 3):
                # Sort positions. The first position in pos_indices will be the leftmost non-dot.
                leftmost_pos = pos_indices[0]
                # The character at leftmost_pos must be r[i].
                # The other two positions will contain the other two characters in any order.
                remaining_chars = [ch for ch in row_chars if ch != r[i]]
                for perm_rem in itertools.permutations(remaining_chars):
                    row = ['.'] * n
                    row[leftmost_pos] = r[i]
                    row[pos_indices[1]] = perm_rem[0]
                    row[pos_indices[2]] = perm_rem[1]
                    possibilities.append(row)
        return possibilities

    all_row_options = [get_possible_rows(i) for i in range(n)]

    def check_compatibility(chosen_rows):
        # Check column constraints
        for j in range(n):
            col_chars = []
            for i in range(n):
                ch = chosen_rows[i][j]
                if ch != '.':
                    col_chars.append((i, ch))
            if len(col_chars) != 3:
                return False
            # Check unique characters
            chars_in_col = [ch for _, ch in col_chars]
            if len(set(chars_in_col)) != 3:
                return False
            # Check topmost character
            topmost_i, topmost_ch = col_chars[0]  # col_chars is naturally sorted by i because we iterate i from 0 to n-1
            if topmost_ch != c[j]:
                return False
        return True

    def backtrack_col_row_combo(rows_chosen, idx):
        if idx == n:
            if check_compatibility(rows_chosen):
                return rows_chosen
            return None

        for option in all_row_options[idx]:
            new_rows = rows_chosen + [option]
            # Pruning: check partial column counts
            valid_so_far = True
            for j in range(n):
                count = 0
                topmost_found = False
                topmost_ch = None
                for i in range(idx + 1):
                    ch = new_rows[i][j]
                    if ch != '.':
                        if not topmost_found:
                            topmost_found = True
                            topmost_ch = ch
                        count += 1
                if count > 3:
                    valid_so_far = False
                    break
                # If we have filled all rows up to idx, and count < 3, it's not necessarily invalid yet if idx < n-1, 
                # but if idx == n-1 and count < 3, it's invalid. 
                # Also, if topmost_found and topmost_ch != c[j], is it necessarily invalid? 
                # Yes, because the topmost char in the final column must be c[j]. If the first non-dot encountered 
                # in the rows we've chosen so far is not c[j], and there are no dots above it, then the topmost 
                # in the final grid will be this char (or a char above it if we hadn't checked, but we did). 
                # Wait, if topmost_found is True, it means there is a non-dot at some row k <= idx. 
                # Any non-dot in rows > idx will be below row k. So the topmost non-dot in the final column 
                # will be at row k or higher (lower index). Since we scan from top down, the first non-dot we 
                # see is the topmost one among the rows we have placed. If there are no non-dots in rows 0..k-1, 
                # then this is indeed the topmost. 
                # So if topmost_found and topmost_ch != c[j], we can prune.
                if topmost_found and topmost_ch != c[j]:
                    valid_so_far = False
                    break

            if not valid_so_far:
                continue

            res = backtrack_col_row_combo(new_rows, idx + 1)
            if res is not None:
                return res
        return None

    res = backtrack_col_row_combo([], 0)
    if res is None:
        return None
    return [''.join(row) for row in res]

def count_ways_to_stair(k: int) -> int:
    if k == 0:
        return 2
    if k == 1:
        return 4
    n = k.bit_length()
    if n == 0:
        return 0
    m = n - 1
    if k == (1 << m):
        return 1
    lower = (1 << m) - 1
    higher = (1 << (m + 1)) - 1
    if k <= lower or k >= higher:
        return 0
    r = k - (1 << m)
    pc = r.bit_count()
    return (1 << pc) - 1 - pc

def count_ways_to_stair(k: int) -> int:
    total = 0
    if k == 0:
        return 2
    if k == 1:
        return 4
    for m in range(0, 40):
        d = (1 << m) - k
        if 0 <= d <= m + 1:
            from math import comb
            total += comb(m + 1, d)
    return total
